// Package pricing is the contract of the examples: the interface pricing rules implement as plugins (in Go, Lua
// or TypeScript), the Host interface the rules call back into, and the data types they exchange. Go plugins
// import this package; the Go guest interprets its source, so it imports only packages the guest allows.
// rule_plg.go is generated by the line below (`go generate ./...`).
package pricing

//go:generate go run github.com/heynemann/go-plg/cmd/plg gen Rule

import "context"

// Item is one line of an order.
type Item struct {
	SKU       string `json:"sku"`
	Quantity  int    `json:"quantity"`
	UnitCents int64  `json:"unitCents"`
}

// Order is what a rule prices.
type Order struct {
	Customer string `json:"customer"`
	Coupon   string `json:"coupon"`
	Items    []Item `json:"items"`
}

// Discount is a rule's verdict: Cents off the order (zero when the rule does not apply) and why.
type Discount struct {
	Reason string `json:"reason"`
	Cents  int64  `json:"cents"`
}

// Rule is a pricing rule. Each plugin is one rule, which validates itself against the service's Limits.
//
//plg:validation Limits
type Rule interface {
	// Discount returns the discount the rule grants order.
	Discount(ctx context.Context, order Order) (Discount, error)
}

// Customers is the service side the rules may call: plg.WithHost[pricing.Customers] makes it the plugins' host.
type Customers interface {
	// Tier returns the customer's loyalty tier: "gold", "silver" or "" for none.
	Tier(ctx context.Context, customer string) (string, error)
}

// Limits is what the service lets a rule grant, the input of each rule's Validate (plg.WithValidation): plg
// calls it before a rule goes live, and a rule that could grant more is rejected with an error issue.
type Limits struct {
	// MaxPercent is the largest percentage off a rule may grant.
	MaxPercent int64 `json:"maxPercent"`
	// MaxCents is the largest fixed amount off a rule may grant.
	MaxCents int64 `json:"maxCents"`
}

// Subtotal returns the order's price before any discount. Go rules call it, so it runs interpreted inside the
// guest, and the service calls the same code natively.
func Subtotal(order Order) int64 {
	var total int64

	for _, item := range order.Items {
		total += int64(item.Quantity) * item.UnitCents
	}

	return total
}
